export const CONTENTFUL_PREVIEW_HOST = 'preview.contentful.com';
export const CONTENTFUL_DELIVERY_HOST = 'cdn.contentful.com';
export const CONTENTFUL_LIVE_PREVIEW_ORIGIN = 'https://app.contentful.com';

