121	  // than tokenised, because a comment carries nothing displayable by definition. The unterminated
122	  // case is dropped to end of input, which is what browsers do.
123	  //
124	  // Not an injection route. Whatever survives the strip still has to clear `ALLOWED_TAGS` below,
125	  // and this parser builds React elements rather than injecting markup, so smuggling of the
126	  // `<!--><script>x</script>-->` kind can only ever end up as inert text.
127	  const source = html.replace(/<!--[\s\S]*?-->/g, '').replace(/<!--[\s\S]*$/, '');
128	
129	  const root: Frame = { tag: null, children: [] };
130	  const stack: Frame[] = [root];
131	  const top = () => stack[stack.length - 1];
132	
133	  // Depth counter for a DROP_CONTENT_TAGS region, so nested same-name tags close correctly.
134	  let dropTag: string | null = null;
135	  let dropDepth = 0;
136	
137	  const pushText = (raw: string) => {
138	    if (!raw) return;
139	    // A list container may only hold <li>; whitespace between items would be an invalid text
140	    // child. Text that is not whitespace is kept, so nothing authored is silently lost.
141	    const parentTag = top().tag;
142	    if (parentTag && LIST_CONTAINERS.has(parentTag) && !raw.trim()) return;
143	    top().children.push(decodeEntities(raw));
144	  };
145	
146	  let cursor = 0;
147	  let match: RegExpExecArray | null;
148	  TAG_RE.lastIndex = 0;
149	
150	  while ((match = TAG_RE.exec(source)) !== null) {
151	    const [full, closing, rawName, attrs] = match;
152	    const tag = rawName.toLowerCase();
153	
154	    if (dropDepth === 0) pushText(source.slice(cursor, match.index));
155	    cursor = match.index + full.length;
156	
157	    if (dropDepth > 0) {
158	      if (tag === dropTag) dropDepth += closing ? -1 : 1;
159	      if (dropDepth === 0) dropTag = null;
160	      continue;
161	    }
162	
163	    if (DROP_CONTENT_TAGS.has(tag)) {
164	      // A void element (`<embed>`) and a self-closing `<svg/>` both open and close in one
165	      // token, so neither starts a region to skip.
166	      if (!closing && !VOID_ELEMENTS.has(tag) && !attrs.trimEnd().endsWith('/')) {
167	        dropTag = tag;
168	        dropDepth = 1;
169	      }
170	      continue;
171	    }
172	
173	    if (closing) {
174	      if (!ALLOWED_TAGS.has(tag)) continue;
175	      // Unwind to the matching frame, searching from the top down so a nested `<li>` closes the
176	      // frame it opened rather than its same-named ancestor. `findIndex` scans from the root, so
177	      // it returned the OUTERMOST match: `<ul><li>a<ul><li>b</li></ul>c</li></ul>` closed the
178	      // inner `li`, the inner `ul` and the outer `li` on one `</li>`, and `c` escaped the list
179	      // entirely. Both nested lists and nested emphasis are authorable in Business Manager.
180	      //
181	      // Not `findLastIndex`: `tsconfig.json` pins `lib` to ES2019 and that file is Tier 1.
182	      //
183	      // A stray `</li>` with no open `<li>` leaves the stack untouched rather than closing
184	      // something it did not open — `depth` stays -1 and the guard below skips it.
185	      let depth = -1;
186	      for (let index = stack.length - 1; index > 0; index -= 1) {
187	        if (stack[index].tag === tag) {
188	          depth = index;
189	          break;
190	        }
191	      }
192	      if (depth <= 0) continue;
193	      while (stack.length > depth) closeTop();
194	      continue;
195	    }
196	
197	    if (VOID_TAGS.has(tag)) {
198	      top().children.push(React.createElement(tag, { key: `${tag}-${top().children.length}` }));
199	      continue;
200	    }
201	
202	    if (!ALLOWED_TAGS.has(tag)) continue; // unwrap: drop the tag, keep whatever it contains
203	    if (attrs.trimEnd().endsWith('/')) continue; // self-closed container has no content
204	    stack.push({ tag, children: [] });
205	  }
206	
207	  if (dropDepth === 0) pushText(source.slice(cursor));
208	
209	  // Unclosed tags still render, with whatever content they collected.
210	  while (stack.length > 1) closeTop();
211	
212	  return root.children;
213	
214	  function closeTop() {
215	    const frame = stack.pop();
216	    /* c8 ignore next -- guarded by the `stack.length > 1` conditions at every call site */
217	    if (!frame?.tag) return;
218	    const parent = top();
219	    parent.children.push(
220	      React.createElement(
221	        frame.tag,
222	        { key: `${frame.tag}-${parent.children.length}` },
223	        frame.children.length ? frame.children : undefined,
224	      ),
225	    );
226	  }
227	};
228	
229	/**
230	 * The visible text of a rich-text value, with all markup removed.
231	 *
232	 * Derived by walking the output of `parseRichText` rather than re-stripping the string, so the
233	 * two can never disagree about what counts as content — a second implementation of the
234	 * drop/unwrap rules would drift the first time one of them changed.
235	 *
236	 * Callers use this to decide whether there is anything to render at all: Business Manager can
237	 * save a field as `<p></p>` or a bare `<br>`, which parses to real nodes but shows nothing, and
238	 * rendering it would leave an empty box still contributing to the layout rhythm.
239	 */
240	export const richTextToPlainText = (html?: string | null): string => nodeText(parseRichText(html));
241	
242	const nodeText = (node: ReactNode): string => {
243	  if (node === null || node === undefined || typeof node === 'boolean') return '';
244	  if (typeof node === 'string' || typeof node === 'number') return String(node);
245	  if (Array.isArray(node)) return node.map(nodeText).join('');
246	  if (React.isValidElement(node)) return nodeText((node.props as { children?: ReactNode }).children);
247	  /* c8 ignore next -- ReactNode also admits portals and iterables, which this parser never emits */
248	  return '';
249	};
250	
251	/** True when a rich-text value would render nothing visible. */
252	export const isBlankRichText = (html?: string | null): boolean => richTextToPlainText(html).trim() === '';
253

